const giftSoldByMonths = `-- name: GiftSoldByMonths :many
SELECT g.months, count(*)::bigint AS sold, coalesce(sum(g.amount_cents), 0)::bigint AS cents
FROM earn_gifts g
WHERE g.workspace_id = $1 AND g.mode = $2 AND g.paid_at >= $3::timestamptz AND g.status IN ('paid','delivered','redeemed','expired')
GROUP BY g.months ORDER BY count(*) DESC, g.months DESC
`

type GiftSoldByMonthsParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	Mode        string    `json:"mode"`
	Since       time.Time `json:"since"`
}

type GiftSoldByMonthsRow struct {
	Months int32 `json:"months"`
	Sold   int64 `json:"sold"`
	Cents  int64 `json:"cents"`
}

// Gifts paid since a time by their period ("7 for a year, 4 for 3 months").
func (q *Queries) GiftSoldByMonths(ctx context.Context, arg GiftSoldByMonthsParams) ([]GiftSoldByMonthsRow, error) {
	rows, err := q.db.Query(ctx, giftSoldByMonths, arg.WorkspaceID, arg.Mode, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GiftSoldByMonthsRow{}
	for rows.Next() {
		var i GiftSoldByMonthsRow
		if err := rows.Scan(&i.Months, &i.Sold, &i.Cents); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

