const giftsPurgeMessages = `-- name: GiftsPurgeMessages :execrows
UPDATE earn_gifts g SET message = '', message_purged_at = $1::timestamptz, updated_at = $1::timestamptz
WHERE g.message <> '' AND (
     g.status = 'abandoned'
  OR (g.status = 'refunded' AND g.refunded_at <= $2::timestamptz)
  OR (g.status = 'expired' AND g.link_expires_at <= $2::timestamptz)
  OR (g.status = 'redeemed' AND EXISTS (SELECT 1 FROM paid_subscriptions s WHERE s.id = g.subscription_id
        AND coalesce(s.ended_at, s.current_period_end) <= $2::timestamptz))
)
`

type GiftsPurgeMessagesParams struct {
	Now      time.Time `json:"now"`
	MonthAgo time.Time `json:"monthAgo"`
}

// Gift messages are kept until the gift ends, plus 30 days; a checkout
// that was never paid loses its message once abandoned.
func (q *Queries) GiftsPurgeMessages(ctx context.Context, arg GiftsPurgeMessagesParams) (int64, error) {
	result, err := q.db.Exec(ctx, giftsPurgeMessages, arg.Now, arg.MonthAgo)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

